const express = require('express');
const speakeasy = require('speakeasy');
const QRCode = require('qrcode');
const { db } = require('../models/database');

const app = express();
app.use(express.json());

app.post('/api/security/mfa/setup/:targetAccountId', async (req, res) => {
  if (!req.user || !req.user.accountId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { targetAccountId } = req.params;

  // Verify that the caller is attempting to setup MFA on their own account
  if (req.user.accountId !== targetAccountId) {
    return res.status(403).json({ error: 'Access denied: cannot initiate MFA setup for another account' });
  }

  const account = await db.accounts.findById(targetAccountId);
  if (!account) {
    return res.status(404).json({ error: 'Target account not found' });
  }

  const secret = speakeasy.generateSecret({
    length: 20,
    name: `AegisSecurity (${account.email})`
  });

  account.tempMfaSecret = secret.base32;
  await account.save();

  const dataUrl = await QRCode.toDataURL(secret.otpauth_url);

  res.json({
    base32Secret: secret.base32,
    qrCode: dataUrl,
    accountId: targetAccountId
  });
});

app.listen(6003);
